<template><div class="page-title">{{names[type]}}</div><div class="toolbar"><el-input v-model="keyword" placeholder="搜索关键词" clearable @keyup.enter="load"/><el-button type="primary" @click="open()">新增</el-button><el-button @click="load">查询</el-button></div><el-card><el-table :data="rows" stripe><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="120"><template #default="{row}" v-if="c.prop==='stage'||c.prop==='status'">{{text(c.prop==='stage'?maps.stage:maps.caseStatus,row[c.prop])}}</template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" v-model:page-size="size" layout="total,prev,pager,next" :total="total" @current-change="load"/></el-card><el-dialog v-model="visible" :title="form.id?'编辑':'新增'" width="520px"><el-form label-width="100px"><el-form-item v-for="f in fields" :key="f.prop" :label="f.label"><el-input v-model="form[f.prop]" :type="f.type||'text'"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
<script setup>import {ref,computed,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {accounts,contacts,opportunities,activities,knowledge} from '../api';import {maps,text} from '../utils/enums';const props=defineProps({type:String});const names={accounts:'客户管理',contacts:'联系人管理',opportunities:'商机管理',activities:'活动管理',knowledge:'知识库'},apis={accounts,contacts,opportunities,activities,knowledge};const configs={accounts:{columns:[['name','名称'],['industry','行业'],['type','类型'],['level','等级'],['phone','电话']],fields:[['name','名称'],['industry','行业'],['phone','电话'],['website','网站'],['description','描述']]},contacts:{columns:[['name','姓名'],['title','职位'],['department','部门'],['phone','电话'],['email','邮箱']],fields:[['name','姓名'],['accountId','客户ID'],['title','职位'],['phone','电话'],['email','邮箱']]},opportunities:{columns:[['name','名称'],['amount','金额'],['stage','阶段'],['probability','概率']],fields:[['name','名称'],['accountId','客户ID'],['amount','金额'],['expectedCloseDate','预计日期'],['description','描述']]},activities:{columns:[['subject','主题'],['type','类型'],['status','状态'],['dueTime','截止时间']],fields:[['subject','主题'],['content','内容'],['relatedId','关联ID'],['dueTime','截止时间']]},knowledge:{columns:[['title','标题'],['category','分类'],['status','状态'],['viewCount','浏览量']],fields:[['title','标题'],['category','分类'],['keywords','关键词'],['content','内容']]}};const cfg=computed(()=>configs[props.type]),columns=computed(()=>cfg.value.columns.map(x=>({prop:x[0],label:x[1]}))),fields=computed(()=>cfg.value.fields.map(x=>({prop:x[0],label:x[1],type:x[0]==='content'||x[0]==='description'?'textarea':null}))),api=apis[props.type],rows=ref([]),total=ref(0),page=ref(1),size=ref(10),keyword=ref(''),visible=ref(false),form=ref({});async function load(){const d=await api.list({page:page.value,size:size.value,keyword:keyword.value});rows.value=d.records;total.value=d.total}function open(x){form.value={...(x||{})};visible.value=true}async function save(){if(form.value.id)await api.update(form.value.id,form.value);else await api.add(form.value);ElMessage.success('保存成功');visible.value=false;load()}async function remove(x){await ElMessageBox.confirm('确认删除？','提示');await api.remove(x.id);load()}onMounted(load)</script>
